reference_solution:
def subarraysDivByK(nums, k):
    cnt = {0: 1}
    total = res = 0
    for x in nums:
        total = (total + x) % k
        res += cnt.get(total, 0)
        cnt[total] = cnt.get(total, 0) + 1
    return res

brute_force_solution:
def subarraysDivByK(nums, k):
    res = 0
    for i in range(len(nums)):
        s = 0
        for j in range(i, len(nums)):
            s += nums[j]
            if s % k == 0:
                res += 1
    return res

